CREATE PROCEDURE [Prenotaz_selectrow]
	@P_30 UniqueIdentifier,
	@sync_scope_local_id Int,
	@sync_scope_restore_count Int
AS
BEGIN
SELECT [side].[Keys], [base].[IdOp], [base].[IdCli], [base].[Codice], [base].[Descrizione], [base].[Costo], [base].[N_Tickets], [base].[Fornitore], [base].[NomeC], [base].[CognomeC], [base].[Tel], [base].[Data], [base].[DataCon], [base].[Cons], [base].[IdOpCo], [base].[Quantita], [base].[SerNum], [base].[Conf], [base].[MsgInv], [base].[NImp], [base].[Annul], [base].[DataConf], [base].[F0], [base].[T0], [base].[N0], [base].[D0], [base].[F1], [base].[T1], [base].[N1], [base].[D1], [side].[sync_row_is_tombstone], [side].[local_update_peer_timestamp] as sync_row_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then COALESCE([side].[restore_timestamp], [side].[local_update_peer_timestamp]) else [side].[scope_update_peer_timestamp] end as sync_update_peer_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_update_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_update_peer_key] end else [side].[scope_update_peer_key] end as sync_update_peer_key, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then [side].[local_create_peer_timestamp] else [side].[scope_create_peer_timestamp] end as sync_create_peer_timestamp, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_create_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_create_peer_key] end else [side].[scope_create_peer_key] end as sync_create_peer_key from [Prenotaz] [base] right join [Prenotaz_tracking] [side] on [base].[Keys] = [side].[Keys] WHERE [side].[Keys] = @P_30
END
